tool_calls:
mkdir -p /home/eval/recon/out
cat > /home/eval/recon/ledger.awk <<'EOF'
BEGIN { OFS="\t" }
FNR == 1 { next }
{
  id=$1; date=$2; a=$4
  gsub(/,/, "", a)
  if (a ~ /^-/) { neg=1; sub(/^-/, "", a) } else neg=0
  split(a, p, ".")
  whole=p[1]+0; frac=p[2]
  while (length(frac)<3) frac=frac "0"
  cents=(whole*100)+(substr(frac,1,2)+0)
  if (substr(frac,3,1)+0 >= 5) cents++
  if (neg) cents=-cents
  print id,date,cents
}
EOF
cat > /home/eval/recon/bank.awk <<'EOF'
BEGIN { FS="\t"; OFS="\t" }
FNR == 1 { next }
{
  id=$1; gsub(/^ +| +$/, "", id); id=toupper(id)
  split($2,d,"/"); date=d[3] "-" d[2] "-" d[1]
  a=$4
  if (a ~ /^-/) { neg=1; sub(/^-/, "", a) } else neg=0
  split(a,p,"."); whole=p[1]+0; frac=p[2]
  while (length(frac)<3) frac=frac "0"
  cents=whole*100+(substr(frac,1,2)+0)
  if (substr(frac,3,1)+0 >= 5) cents++
  if (neg) cents=-cents
  key=id SUBSEP date SUBSEP cents
  if (key in seen) { duplicates++; next }
  seen[key]=1
  print id,date,cents
}
END { print duplicates+0 > "/home/eval/recon/bank_duplicates" }
EOF
gawk --csv -f /home/eval/recon/ledger.awk /home/eval/recon/ledger.csv > /home/eval/recon/ledger.norm
gawk -f /home/eval/recon/bank.awk /home/eval/recon/bank.tsv > /home/eval/recon/bank.norm
cat > /home/eval/recon/report.awk <<'EOF'
BEGIN { FS="\t"; OFS="" }
FILENAME == ARGV[1] {
  id=$1; ld[id]=$2; la[id]=$3+0; ledger_count++; ltotal+=la[id]; next
}
FILENAME == ARGV[2] {
  id=$1; bd[id]=$2; ba[id]=$3+0; bank_count++; btotal+=ba[id]; next
}
END {
  getline dup < "/home/eval/recon/bank_duplicates"; close("/home/eval/recon/bank_duplicates")
  n=asorti(ld, ids)
  for (i=1;i<=n;i++) {
    id=ids[i]
    if (id in bd) {
      if (la[id]==ba[id] && ld[id]==bd[id]) matched++
      if (la[id]!=ba[id]) amount[++am_n]=id
      if (ld[id]!=bd[id]) date[++dt_n]=id
    } else missing_bank[++mb_n]=id
  }
  n=asorti(bd, ids)
  for (i=1;i<=n;i++) if (!(ids[i] in ld)) missing_ledger[++ml_n]=ids[i]
  print "ledger_rows: ",ledger_count
  print "bank_rows: ",bank_count
  print "duplicate_bank_rows: ",dup+0
  print "ledger_total: ",money(ltotal)
  print "bank_total: ",money(btotal)
  print "matched: ",matched+0
  print "amount_mismatch: ",am_n+0
  for(i=1;i<=am_n;i++) { id=amount[i]; print "  ",id," ledger=",money(la[id])," bank=",money(ba[id]) }
  print "date_mismatch: ",dt_n+0
  for(i=1;i<=dt_n;i++) { id=date[i]; print "  ",id," ledger=",ld[id]," bank=",bd[id] }
  print "missing_in_bank: ",mb_n+0
  for(i=1;i<=mb_n;i++) print "  ",missing_bank[i]
  print "missing_in_ledger: ",ml_n+0
  for(i=1;i<=ml_n;i++) print "  ",missing_ledger[i]
}
function money(c, sign, abs, d, r) {
  sign=(c<0?"-":""); abs=(c<0?-c:c)
  d=int(abs/100); r=abs%100
  return sign d "." (r<10?"0":"") r
}
EOF
gawk -f /home/eval/recon/report.awk /home/eval/recon/ledger.norm /home/eval/recon/bank.norm > /home/eval/recon/out/reconciliation.txt
cat /home/eval/recon/out/reconciliation.txt

